2430: # The engine branch of Resolve-ReviewerIdentity (see the engine table below): the provider is
2431: # a free label (default: the engine's DefaultProvider), the model is REQUIRED (for agy the full
2432: # id with its tier), the endpoint is the engine itself - HostName 'engine:<name>', CompatString
2433: # 'cc-engine-v1|<name>', Fingerprint its SHA-256 (a thread of the engine never mixes with a codex
2434: # thread), ProviderConfig { engine; launcher }. Error: an unknown engine or a missing model.
2435: function Resolve-EngineIdentity {
2436:     param($Identity, [string]$Engine, [string]$Provider, [string]$Model, [string]$Launcher)
2437:     $id = $Identity
2438:     $id.Engine = $Engine
2439:     $spec = Get-EngineSpec -Name $Engine
2440:     if (-not $spec) {
2441:         $id.Error = "unknown engine '$Engine' (engines: $($script:EngineNames -join ', '))"
2442:         $id.Lineage = Format-Lineage -Provider $id.Provider -Model $id.Model
2443:         return $id
2444:     }
2445:     if ($Provider) { $id.Provider = $Provider; $id.ProviderSource = '-Provider' }
2446:     else { $id.Provider = [string]$spec.DefaultProvider; $id.ProviderSource = 'engine default' }
2447:     if ($Model) { $id.Model = $Model; $id.ModelSource = '-Model' }
2448:     else { $id.Error = "the $Engine engine needs a model: pass -Model <id> (the full model id, e.g. $($spec.ModelExample)) or name it in the roster entry" }
2449:     $id.HostName = [string]$spec.HostName
2450:     $id.WireApi = ''
2451:     $id.BaseUrl = ''
2452:     $pc = New-Object PSObject
2453:     $pc | Add-Member -NotePropertyName 'engine' -NotePropertyValue $Engine
2454:     $pc | Add-Member -NotePropertyName 'launcher' -NotePropertyValue $(if ($Launcher) { $Launcher } else { '' })
2455:     $id.ProviderConfig = $pc
2456:     $id.Display = "engine $Engine ($(if ($Launcher) { $Launcher } else { "$($spec.Command) CLI not found" }))"
2457:     $id.ConfigPath = ''
2458:     $id.Lineage = Format-Lineage -Provider $id.Provider -Model $id.Model
2459:     if (-not $id.Error) {
2460:         $id.Resolved = $true
2461:         $id.CompatString = [string]$spec.CompatString
2462:         $id.Fingerprint = Get-Sha256Hex ($script:Utf8NoBom.GetBytes($id.CompatString))
2463:     }
2464:     return $id
2465: }
