2486: # Per-run Codex config overrides: -CodexConfig and a roster entry's codex_config follow the
2487: # same rules. Each item is key=value; one string may carry several, split only at a comma
2488: # that starts the next key=, so a value like [1,2] stays whole. Keys that would change what
2489: # the ledger records (model, model_provider, profile, model_reasoning_effort,
2490: # model_providers.*) are refused. A value starting with ~/ or ~\ gets the home directory
2491: # ($HOME, else USERPROFILE) and forward slashes (Codex does not expand ~; on Windows
2492: # `~/...` fails with os error 123). A value that is not a TOML literal is wrapped in double
2493: # quotes (Codex parses the value as TOML and falls back to a literal string, so a bare path
2494: # is a TOML string either way). { Items (string[], as passed to codex and recorded in the
2495: # ledger); Error ('' or the message, prefixed by $Label) }.
2496: function ConvertFrom-CodexConfigItems {
2497:     param([string[]]$Values, [string]$Label = '-CodexConfig')
2498:     $items = New-Object System.Collections.Generic.List[string]
2499:     foreach ($cfgArg in @($Values)) {
2500:         if (-not $cfgArg -or -not $cfgArg.Trim()) { continue }
2501:         foreach ($item in ($cfgArg.Trim() -split ',(?=\s*[A-Za-z0-9_.]+=)')) {
2502:             $item = $item.Trim()
2503:             if ($item -notmatch '^[A-Za-z0-9_.]+=.+$') {
2504:                 return [pscustomobject]@{ Items = [string[]]@(); Error = "$Label '$item' is malformed: expected key=value (key: letters, digits, _ and .; a non-empty value)." }
2505:             }
2506:             $cfgKey = $item.Substring(0, $item.IndexOf('='))
2507:             $cfgValue = $item.Substring($item.IndexOf('=') + 1)
2508:             if (@('model', 'model_provider', 'profile', 'model_reasoning_effort', 'model_providers') -ccontains $cfgKey -or $cfgKey.StartsWith('model_providers.', [StringComparison]::Ordinal)) {
2509:                 return [pscustomobject]@{ Items = [string[]]@(); Error = "$Label '$item' is refused: $cfgKey is part of the reviewer identity and effort the bridge records (use -Model / -Provider / -Effort; providers belong in the Codex config)." }
2510:             }
2511:             if ($cfgValue -match '^~[\\/]') {
2512:                 $homeDir = $HOME
2513:                 if (-not $homeDir) { $homeDir = $env:USERPROFILE }
2514:                 $cfgValue = (($homeDir.TrimEnd([char]'\', [char]'/') + $cfgValue.Substring(1)) -replace '\\', '/')
2515:             }
2516:             if ($cfgValue -notmatch '^(["''0-9\[{]|true$|false$)') { $cfgValue = '"' + (ConvertTo-TomlBasicString $cfgValue) + '"' }
2517:             $items.Add("$cfgKey=$cfgValue")
2518:         }
2519:     }
2520:     return [pscustomobject]@{ Items = [string[]]$items.ToArray(); Error = '' }
2521: }
