2597: function Get-SchemaTransport {
2598:     param($Identity)
2599:     $hostName = [string]$Identity.HostName
2600:     if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) {
2601:         return [pscustomobject]@{ Transport = $script:EffortCaps[$hostName].SchemaTransport; Basis = "$($script:EffortCapsVersion): $hostName" }
