2608: function Resolve-EffortPlan {
2609:     param($Identity, [string]$Requested, [string]$Native = '')
2610:     $plan = [pscustomobject]@{ Requested = $Requested; Sent = ''; Mapping = ''; Caps = $script:EffortCapsVersion; Basis = ''; Error = '' }
2611:     if ($Native) {
2612:         $plan.Requested = $Native; $plan.Sent = $Native; $plan.Mapping = 'native'; $plan.Basis = '-NativeEffort, sent verbatim'
2613:         return $plan
2614:     }
2615:     $hostName = [string]$Identity.HostName
2616:     $model = [string]$Identity.Model
2617:     $cap = $null
2618:     if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) { $cap = $script:EffortCaps[$hostName] }
2619:     if ($cap -and $cap.Vocabulary -eq 'model-tier') {
2620:         # An engine whose model id carries the reasoning tier: nothing is sent.
2621:         $plan.Sent = $null
2622:         $plan.Mapping = 'model-tier'
2623:         $plan.Basis = "$($script:EffortCapsVersion): engine $($hostName -replace '^engine:', ''), the tier is part of the model id"
2624:         return $plan
2625:     }
2626:     if (-not $cap) {
2627:         $hostLabel = if ($hostName) { $hostName } else { 'unknown-host' }
2628:         # Ordinal order: the same list on Windows PowerShell 5.1 (NLS ignores '-') and pwsh 7 (ICU).
2629:         $declaredHosts = [string[]]@($script:EffortCaps.Keys | Where-Object { $_ -notlike 'engine:*' })
2630:         [Array]::Sort($declaredHosts, [StringComparer]::Ordinal)
2631:         $declared = $declaredHosts -join ', '
2632:         $plan.Error = "no effort vocabulary declared for $hostLabel ($($script:EffortCapsVersion) declares $declared); pass -NativeEffort <value> to send a value verbatim"
2633:         return $plan
2634:     }
2635:     if (($null -ne $cap.Models) -and (($Identity.ModelSource -eq 'unknown') -or -not ($cap.Models -ccontains $model))) {
2636:         $plan.Error = "no effort vocabulary declared for model '$model' on $hostName ($($script:EffortCapsVersion) declares: $($cap.Models -join ', ')); pass -NativeEffort <value> to send a value verbatim"
2637:         return $plan
2638:     }
2639:     $v = $script:EffortVocabularies[$cap.Vocabulary]
2640:     $plan.Sent = $v.Map[$Requested]
2641:     $plan.Mapping = $v.Mapping
2642:     $plan.Basis = if ($null -eq $cap.Models) { "$($script:EffortCapsVersion): $hostName, any model" } else { "$($script:EffortCapsVersion): $hostName, $model" }
2643:     return $plan
2644: }
