2646: # ----------------------------------------------------------------------------- peak windows
2647: #
2648: # CODEX_CONSULT_PEAK_<PROVIDER> = "<days> <HH:MM>-<HH:MM> <+HH:MM|-HH:MM>" (the provider
2649: # name upper-cased, every character outside A-Z 0-9 replaced by _), e.g.
2650: # CODEX_CONSULT_PEAK_ZAI="Mon-Fri 14:00-18:00 +08:00". Days: *, a day (Mon), a range
2651: # (Mon-Fri; it may wrap: Fri-Mon) or a comma list of those. Optional
2652: # CODEX_CONSULT_PEAK_<PROVIDER>_EXCEPT = comma-separated YYYY-MM-DD or
2653: # YYYY-MM-DD..YYYY-MM-DD: those calendar dates (in the schedule's offset) are off-peak all
2654: # day. Evaluated ONCE at launch in the fixed offset: start inclusive, end exclusive (24:00
2655: # = midnight); an overnight window (start > end) spans midnight and its day check applies
2656: # to the day it STARTED. peak = $true | $false; $null = no schedule (unknown). A long
2657: # consultation that starts off-peak may still run into the window.
2658: $script:DayNames = @('sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat')
2659: 
2660: # The clock of the peak evaluations. TEST HOOK: CODEX_CONSULT_NOW = one or more ISO
2661: # timestamps with an offset, comma-separated; the k-th evaluation of a run uses the k-th
2662: # (the last one repeats), so a test can put the early check off-peak and the launch-time
2663: # check inside the window. Unset: the system clock. { Now (DateTimeOffset); Iso; FromEnv;
2664: # Error }. -Peek reads the value the next evaluation would get without consuming it (the
2665: # endpoint-health reading of the preflight and codex-providers.ps1 use it).
2666: $script:ConsultClockCalls = 0
2667: function Get-ConsultClock {
2668:     param([switch]$Peek)
2669:     $raw = [string]$env:CODEX_CONSULT_NOW
2670:     $call = $script:ConsultClockCalls
2671:     if (-not $Peek) { $script:ConsultClockCalls++ }
2672:     if (-not $raw.Trim()) {
2673:         $n = [DateTimeOffset]::Now
2674:         return [pscustomobject]@{ Now = $n; Iso = $n.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $false; Error = '' }
2675:     }
2676:     $items = @($raw.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
2677:     $parsed = New-Object System.Collections.Generic.List[DateTimeOffset]
2678:     foreach ($item in $items) {
2679:         $dto = [DateTimeOffset]::MinValue
2680:         if ($item -notmatch '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?([+-][0-9]{2}:[0-9]{2}|Z)$' -or -not [DateTimeOffset]::TryParse($item, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$dto)) {
2681:             return [pscustomobject]@{ Now = $null; Iso = ''; FromEnv = $true; Error = "CODEX_CONSULT_NOW='$raw' is malformed: bad token '$item' (a test hook: ISO timestamps with an offset, e.g. 2026-09-24T13:59:59+08:00, comma-separated)" }
2682:         }
2683:         $parsed.Add($dto)
2684:     }
2685:     $pick = $parsed[[Math]::Min($call, $parsed.Count - 1)]
2686:     return [pscustomobject]@{ Now = $pick; Iso = $pick.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); FromEnv = $true; Error = '' }
2687: }
