2594: # { Transport ('output-schema' | 'prompt-only'); Basis } for the identity's endpoint;
2595: # 'prompt-only' is the safe default for an endpoint caps-v1 does not declare (a
2596: # json_schema response format it may reject would fail the whole run).
2597: function Get-SchemaTransport {
2598:     param($Identity)
2599:     $hostName = [string]$Identity.HostName
2600:     if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) {
2601:         return [pscustomobject]@{ Transport = $script:EffortCaps[$hostName].SchemaTransport; Basis = "$($script:EffortCapsVersion): $hostName" }
2602:     }
2603:     $label = if ($hostName) { $hostName } else { 'unknown-host' }
2604:     return [pscustomobject]@{ Transport = 'prompt-only'; Basis = "default for an endpoint $($script:EffortCapsVersion) does not declare: $label" }
2605: }
